sealed class SearchApiException: kotlin.Exception() {
    
    class Other(
        
        val `reason`: kotlin.String
        ) : SearchApiException() {
        override val message
            get() = "reason=${ `reason` }"
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<SearchApiException> {
        override fun lift(error_buf: RustBuffer.ByValue): SearchApiException = FfiConverterTypeSearchApiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeSearchApiError : FfiConverterRustBuffer<SearchApiException> {
    override fun read(buf: ByteBuffer): SearchApiException {
        

        return when(buf.getInt()) {
            1 -> SearchApiException.Other(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: SearchApiException): ULong {
        return when(value) {
            is SearchApiException.Other -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`reason`)
            )
        }
    }

    override fun write(value: SearchApiException, buf: ByteBuffer) {
        when(value) {
            is SearchApiException.Other -> {
                buf.putInt(1)
                FfiConverterString.write(value.`reason`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



